import {renderCartMockup} from './cart-mockup.mjs';
import {addressPickerHTML,bindAddressPicker} from './address-picker.mjs';
import {hasPersonalisation,paymentDescription,freightEstimate} from './purchase-flow.mjs';
import {paymentMethodsHTML} from './payment-methods.mjs';
import {fromInc,quoteAmount,vatLabel,customerType,setCustomerType} from './customer-pricing.mjs';
import {launchConfig,launchMessage} from './launch-config.mjs';
import {LEGAL_VERSION,prepaymentConsent} from './legal-consent.mjs';
import {getLanguage} from './i18n-core.mjs';
import {readCart,writeCart,fetchQuote,kroner,escape} from './pf-cart.mjs?v=24';
import {loadFile} from './storage.mjs';

const get=async url=>{const response=await fetch(url);if(!response.ok)throw Error('Oplysningerne kunne ikke hentes.');return response.json();};
export function checkoutPage(adminTest=false){if(!adminTest&&new URLSearchParams(location.search).get('test')==='1')return '<section class="wrap section" id="admin-checkout-test"><h1>Betalingstest</h1><p>Kontrollerer administratoradgang og testtilstand…</p></section>';const personalised=hasPersonalisation(readCart());if(!launchConfig.ordersEnabled&&!adminTest)return `<section class="wrap section pf-checkout"><p class="eyebrow">VI ÅBNER SNART</p><h1>Dit design kan godt være klar før os.</h1><p class="intro">${launchMessage}</p><p>Din kurv er gemt i denne browser, så du kan arbejde videre med dit design.</p><a class="button" href="/kurv">Tilbage til kurven →</a></section>`;return `<section class="wrap section pf-checkout"><nav class="purchase-path" aria-label="Købsforløb"><span class="complete"><i>✓</i><b>Produkt</b></span><span class="complete"><i>✓</i><b>Design</b></span><span class="complete"><i>✓</i><b>Kurv</b></span><span class="active" aria-current="step"><i>4</i><b>Betaling</b></span><span><i>5</i><b>${personalised?'Korrektur':'Levering'}</b></span></nav><h1>${adminTest?'Betalingstest':'Levering og betaling'}</h1>${adminTest?'<p role="status"><strong>Kun testkort.</strong> Kortnummer: 1000 0000 0000 0008 · Udløb: 12/30 · Kontrolcifre: 208. Ingen PF-afsendelse eller ordremail. Din kurv beholdes efter testen.</p>':''}<div class="checkout-intro"><p>Udfyld leveringsadressen. Du ser fragt og den samlede pris, før du går til betaling.</p><details><summary>Sådan fungerer betalingen</summary><p>Du handler som gæst uden at oprette en konto. ${paymentDescription(readCart())} Hvis reservationen udløber inden da, beder vi dig godkende betalingen igen.</p></details></div><div class="cart-layout"><form id="pf-checkout-form" data-admin-test="${adminTest}"><fieldset class="checkout-legal checkout-customer-type"><legend>Privat eller erhverv</legend><label>Køber som<select name="customerType" required><option value="">Vælg kundetype</option><option value="consumer">Privatperson</option><option value="business">Erhverv</option></select></label><div id="checkout-business" hidden><div class="form-grid"><label>Firmanavn *<input name="billingCompany" autocomplete="organization" maxlength="200" disabled></label><label>CVR-nummer *<input name="billingCvr" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" disabled></label><label>Faktura-e-mail *<input name="billingEmail" type="email" maxlength="254" disabled></label><label>Reference (valgfrit)<input name="billingReference" maxlength="200" disabled></label></div></div></fieldset><h2>Leveringsadresse</h2><div class="form-grid"><label>Navn *<input name="name" autocomplete="name" required maxlength="200"></label><label>E-mail *<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Telefon *<input name="phone" type="tel" autocomplete="tel" required maxlength="40"></label><label>Virksomhed<input name="company" autocomplete="organization" maxlength="200"></label>${addressPickerHTML()}</div><fieldset class="checkout-legal"><legend>Kundetype og vilkår</legend><p class="small">Ved erhvervskøb gælder korte reklamationsfrister, produktionstolerancer og begrænset ansvar som beskrevet i afsnit 13.</p><label class="legal-check"><input type="checkbox" name="termsAccepted" required><span>Jeg accepterer <a href="/handelsbetingelser" target="_blank" rel="noopener">handelsbetingelserne</a>.</span></label><label class="legal-check" ${!personalised?'hidden':''}><input type="checkbox" name="personalised" ${personalised?'required':'disabled'}><span>Jeg er informeret om, at varer med mit eget logo, navn, tekst eller individuelle design ikke har fortrydelsesret. Reklamationsretten berøres ikke.</span></label><label class="legal-check" ${!personalised?'hidden':''}><input type="checkbox" name="prepayment" ${personalised?'required':'disabled'}><span>${prepaymentConsent.da}</span></label><p class="small">Se <a href="/privatlivspolitik" target="_blank" rel="noopener">privatlivspolitikken</a>. Oplysninger til ordren bruges ikke automatisk til marketing. <a href="/marketing" target="_blank" rel="noopener">Modtag tilbud (valgfrit)</a>.</p></fieldset><p class="error" id="pf-checkout-error" role="alert"></p><button class="button wide" type="submit" disabled>${adminTest?'Åbn testbetaling →':'Bestil med betalingspligt →'}</button><p class="small muted">Visa, Mastercard, Apple Pay, Google Pay og MobilePay vises på den sikre betalingsside. Du modtager status på e-mail.</p></form><aside class="cart-summary"><h2>Din ordre</h2><div id="pf-checkout-summary" aria-live="polite">Beregner pris…</div><a class="checkout-back-cart" href="/kurv">← Tilbage til kurv</a>${paymentMethodsHTML}</aside></div></section>`;}
export function orderPage(){const id=new URLSearchParams(location.search).get('checkout')||'';return `<section class="wrap section pf-checkout"><nav class="purchase-path" aria-label="Købsforløb"><span class="complete"><i>✓</i><b>Produkt</b></span><span class="complete"><i>✓</i><b>Design</b></span><span class="complete"><i>✓</i><b>Kurv</b></span><span class="complete"><i>✓</i><b>Betaling</b></span><span class="active" aria-current="step"><i>5</i><b>Status</b></span></nav><p class="eyebrow">DIN ORDRE</p><h1>Ordrestatus</h1><div class="review-complete"><p id="pf-order-status" aria-live="polite">Kontrollerer betalingen…</p><div id="pf-order-tracking"></div><button type="button" id="pf-reauthorize" class="button" hidden>Godkend betalingen igen</button>${id?`<p class="small muted">Ordreference: ${escape(id)}</p>`:''}<a class="text-link" href="/produkter">Tilbage til produkterne</a></div></section>`;}
export async function bindCheckout(notify){
 const gate=document.querySelector('#admin-checkout-test');if(gate){try{const response=await fetch('/api/admin/checkout-test/status'),config=await response.json();if(!response.ok||!config.ready)throw Error(config.error||config.reason||'Testadgang er ikke klar.');if(!gate.isConnected)return;gate.outerHTML=checkoutPage(true);return bindCheckout(notify);}catch(error){if(gate.isConnected){gate.replaceChildren();const message=document.createElement('p');message.textContent=error.message;const login=document.createElement('a');login.href='/admin';login.textContent='Åbn medarbejderlogin →';gate.append(message,login);}return;}}
 const form=document.querySelector('#pf-checkout-form');if(form){const adminTest=form.dataset.adminTest==='true';const button=form.querySelector('button[type=submit]'),summary=document.querySelector('#pf-checkout-summary'),error=document.querySelector('#pf-checkout-error'),lines=readCart();
  bindAddressPicker(form);
  form.elements.customerType.value=customerType();
  let refreshSummary=()=>{};
  const business=document.querySelector('#checkout-business');
  const syncCustomer=()=>{const active=form.elements.customerType.value==='business';business.hidden=!active;for(const field of business.querySelectorAll('input')){field.disabled=!active;field.required=active&&field.name!=='billingReference';}};
  form.elements.customerType.addEventListener('change',()=>{setCustomerType(form.elements.customerType.value);syncCustomer();});syncCustomer();
  const onPricingChange=()=>{if(!form.isConnected){window.removeEventListener('customer-pricing-change',onPricingChange);return;}form.elements.customerType.value=customerType();syncCustomer();refreshSummary();};window.addEventListener('customer-pricing-change',onPricingChange);
  if(!lines.length){summary.textContent='Kurven er tom.';return;}
  try{const [quote,config,fulfillment]=await Promise.all([fetchQuote(lines),get(adminTest?'/api/admin/checkout-test/status':'/api/checkout/status'),fetch('/api/checkout/fulfillment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})}).then(response=>{if(!response.ok)throw Error('Forsendelserne kunne ikke vurderes.');return response.json();})]);if(!document.contains(form))return;
   if(quote.totalIncVat===null){summary.innerHTML=`<p class="error">${escape(quote.message||'Prisen mangler.')}</p>`;return;}
   const freight=freightEstimate(fulfillment,config),freightExVat=freight?.exVat??null,freightIncVat=freight?.incVat??null;refreshSummary=()=>{summary.innerHTML=`<dl class="pf-price-breakdown"><div><dt>Varer og tryk ${vatLabel()}</dt><dd>${kroner(quoteAmount(quote))}</dd></div><div><dt>Fragt ${vatLabel()}</dt><dd>${freightIncVat!==null?kroner(fromInc(freightIncVat,freightExVat)):'Afventer'}</dd></div>${customerType()==='business'?`<div><dt>Subtotal ekskl. moms</dt><dd>${freightExVat!==null?kroner(quote.net+freightExVat):'Afventer'}</dd></div><div><dt>Moms (25 %)</dt><dd>${freightIncVat!==null?kroner(quote.vat+freightIncVat-freightExVat):'Afventer'}</dd></div>`:''}<div class="pf-price-total"><dt>Til betaling inkl. moms</dt><dd>${freightIncVat!==null?kroner(quote.totalIncVat+freightIncVat):'Afventer'}</dd></div></dl>`;
   const delivery=config.deliveryTerms?.[getLanguage()];if(delivery){const info=document.createElement('p');info.textContent=delivery;summary.append(info);}
   };refreshSummary();
   if(!fulfillment.ready){error.textContent=fulfillment.message;return;}
   if(!config.ready){error.textContent=`Betaling er endnu ikke åben: ${config.reason}`;return;}const delivery=config.deliveryTerms?.[getLanguage()];if(!delivery){error.textContent='Leveringstiden skal afklares før onlinebestilling.';return;}button.disabled=false;
  }catch(e){error.textContent=e.message;return;}
  form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;button.disabled=true;error.textContent='';button.textContent='Forbereder betaling…';
   try{const lines=readCart(),ids=[...new Set(lines.filter(line=>!line.companyTemplate).flatMap(line=>line.decorations.flatMap(deco=>(deco.artworks||[]).map(art=>art.logo.id))))],artworks=[];
    for(const id of ids){const blob=await loadFile(id);if(!blob)throw Error('En logofil mangler i browseren. Åbn produktet og upload den igen.');const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));artworks.push({id,base64:btoa(binary)});}
    const mockups=[];
    for(const [lineIndex,line] of lines.entries()){
     try{
      const product=await get('/api/pf-product/'+encodeURIComponent(line.productId)),variant=product.variants.find(v=>v.sku===line.sku);
      for(const [decorationIndex,design] of line.decorations.entries()){
       try{
        let base64;
        if(line.companyTemplate){const r=await fetch(`/api/company/previews/${encodeURIComponent(line.companyTemplate.id)}/${decorationIndex}`);if(!r.ok)continue;const bytes=new Uint8Array(await r.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));base64=btoa(binary);}
        else{const canvas=await renderCartMockup(product,variant.options.find(o=>o.id===design.optionId),design);base64=canvas.toDataURL('image/png').split(',')[1];}
        if(base64.length<=2*1024*1024&&mockups.reduce((n,m)=>n+m.base64.length,0)+base64.length<=8*1024*1024)mockups.push({lineIndex,decorationIndex,base64});
       }catch{/* An unavailable preview must not prevent checkout. */}
      }
     }catch{}
    }
    const shipping=Object.fromEntries(new FormData(form)),response=await fetch(adminTest?'/api/admin/checkout-test/session':'/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json',...(adminTest?{'X-Smerch-Admin':'1'}:{})},body:JSON.stringify({lines,shipping,artworks,mockups,billing:{company:form.elements.billingCompany.value,cvr:form.elements.billingCvr.value,email:form.elements.billingEmail.value,reference:form.elements.billingReference.value},legal:{version:LEGAL_VERSION,locale:getLanguage(),customerType:form.elements.customerType.value,accepted:form.elements.termsAccepted.checked,personalised:form.elements.personalised.checked,prepayment:form.elements.prepayment.checked}})}),result=await response.json();if(!response.ok)throw Error(result.error||'Betalingen kunne ikke startes.');sessionStorage.setItem('pf-checkout-id',result.id);sessionStorage.setItem('pf-checkout-cart',JSON.stringify(lines));location.assign(result.url);
   }catch(e){error.textContent=e.message;button.disabled=false;button.textContent=adminTest?'Åbn testbetaling →':'Bestil med betalingspligt →';notify?.(e.message);}
  };
 }
 const status=document.querySelector('#pf-order-status');if(status){const id=new URLSearchParams(location.search).get('checkout');if(!/^pay-[a-f0-9-]{36}$/.test(id||'')){status.textContent='Betalingsreferencen mangler.';return;}
  const retry=document.querySelector('#pf-reauthorize'),tracking=document.querySelector('#pf-order-tracking');retry.onclick=async()=>{retry.disabled=true;try{const response=await fetch(`/api/checkout/${encodeURIComponent(id)}/reauthorize`,{method:'POST'}),result=await response.json();if(!response.ok)throw Error(result.error||'Betalingen kunne ikke startes igen.');location.assign(result.url);}catch(error){status.textContent=error.message;retry.disabled=false;}};
  const refresh=async()=>{try{const order=await get(`/api/checkout/${encodeURIComponent(id)}`);if(!document.contains(status))return;const finalStep=document.querySelector('.purchase-path [aria-current=step] b');if(finalStep)finalStep.textContent=order.personalised?'Korrektur':'Levering';retry.hidden=order.adminTest||!['authorization_expired','expired','payment_failed'].includes(order.status);if(!order.adminTest&&['authorized','capture_reconciliation','paid'].includes(order.status)&&sessionStorage.getItem('pf-checkout-id')===id&&sessionStorage.getItem('pf-checkout-cart')===JSON.stringify(readCart()))writeCart([],{track:false});if(order.status==='authorized')status.innerHTML=`<strong>${kroner(order.totalIncVat)} er reserveret, men ikke hævet.</strong><br>${order.personalised?'Vi afventer den endelige korrektur og produktionsgodkendelse.':'Vi behandler din ordre. Betalingen hæves tidligst ved afsendelse.'}${order.authorizationExpiresAt?` Reservationen udløber ${new Date(order.authorizationExpiresAt).toLocaleString('da-DK')}.`:''}`;else if(order.status==='capture_reconciliation')status.textContent='Godkendelsen er registreret. Vi afstemmer hævningen hos betalingsudbyderen.';else if(order.status==='paid'){const pf=order.pfOrders||[],released=pf.length>0&&pf.every(row=>['approval_recorded','processing','shipped'].includes(row.status));status.innerHTML=`<strong>Betalingen på ${kroner(order.totalIncVat)} er hævet.</strong><br>${order.personalised?(released?'Produktionspartneren har kvitteret for korrekturgodkendelsen.':'Produktionen afventer kvittering på korrekturgodkendelsen.'):'Dine varer er afsendt. Se leveringsstatus nedenfor.'}`;}else if(order.status==='authorization_expired')status.textContent='Reservationen er udløbet. Godkend betalingen igen, så ordren kan fortsætte.';else if(order.status==='expired')status.textContent='Betalingslinket er udløbet. Godkend betalingen igen.';else if(order.status==='payment_failed')status.textContent='Betalingen lykkedes ikke. Prøv at godkende den igen.';else status.textContent='Vi afventer bekræftelse på reservationen. Siden opdateres automatisk.';if(order.adminTest)status.textContent=order.status==='authorized'?'Testbetaling godkendt. Smerch har modtaget og verificeret QuickPays betalingsbesked. Ingen PF-ordre eller ordremail er sendt.':`Betalingstest: ${order.status}. Afventer godkendt testbetaling og betalingsbesked.`;tracking.replaceChildren();for(const pf of order.pfOrders||[]){if(pf.status==='shipped'){const p=document.createElement('p');p.textContent=`Afsendt${pf.carrier?' med '+pf.carrier:''}. Tracking: ${Array.isArray(pf.tracking)?pf.tracking.join(', '):String(pf.tracking||'Afventer')}`;tracking.append(p);}}if(['authorized','capture_reconciliation','paid','awaiting_payment'].includes(order.status))setTimeout(refresh,5000);}catch{status.textContent='Ordrestatus kunne ikke hentes. Genindlæs siden om lidt.';}};refresh();
 }
}
